                      {avg!=null && <div style={{textAlign:"right"}}><div style={{fontSize:24,fontWeight:700,color:avg>=70?"var(--accent-teal)":avg>=50?"var(--accent-amber)":"var(--accent-rose)"}}>{avg}%</div><div style={{fontSize:12,color:"var(--text-secondary)"}}>Average score</div></div>}
                    </div>
                    {stuAssign.length===0 ? <p style={{color:"var(--text-muted)",fontSize:13}}>No assignments given yet.</p>
                      : <table className="data-table"><thead><tr><th>Assignment</th><th>Status</th><th>Score</th></tr></thead>
                        <tbody>{stuAssign.map(a => (
                          <tr key={a.id}><td>{a.title}</td><td><span className={`badge ${a.status==="graded"?"badge-green":a.status==="submitted"?"badge-amber":"badge-rose"}`}>{a.status}</span></td><td>{a.obtainedMarks!=null?`${a.obtainedMarks}/${a.totalMarks}`:"—"}</td></tr>
                        ))}</tbody>
                      </table>
                    }
                  </div>
                );
              })
            }
          </>
        )}

        {/* NOTIFICATIONS */}
        {page === "notifications" && (
          <>
            <div className="page-header" style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
              <div><h1>Notifications</h1><p>Updates from your students</p></div>
              {unread > 0 && <button className="btn btn-outline" onClick={markAllRead}>Mark all read</button>}
            </div>
            <div className="card">
              {notifications.length === 0
                ? <div className="empty-state"><div className="empty-icon">🔔</div><p>No notifications yet.</p></div>
                : <div className="activity-feed">{notifications.map(n => (
                  <div key={n.id} className="activity-item" style={{cursor:"pointer",opacity:n.read?0.6:1}} onClick={() => markNotifRead(n.id)}>
                    <div className="activity-dot" style={{background:!n.read?"var(--accent-blue)":"var(--text-muted)",width:10,height:10}}></div>
                    <div style={{flex:1}}>
                      <div className="activity-text" style={{fontWeight:n.read?400:600}}>{n.message}</div>
                      <div className="activity-time">{format(new Date(n.createdAt),"MMM d, yyyy · h:mm a")}</div>
                    </div>
                    {!n.read && <span className="badge badge-blue" style={{flexShrink:0}}>New</span>}
                  </div>
                ))}</div>
              }
            </div>
          </>
        )}
